package org.overengineer.bettacraft.genetics;

import java.util.List;

/**
 * Named betta colours (tints for the greyscale masks). Built-in table generated by tools/assetgen/palette.py
 * ({@link BettaColorTable}); since M5 datapack-driven ({@code data/<ns>/bettacraft/colors/*.json}, see {@link GeneticsData}).
 */
public final class BettaColors {
    /** Neutral grey for unknown (e.g. removed datapack) colour ids. */
    public static final int FALLBACK_RGB = 0x9A9A9A;

    private BettaColors() {}

    /** Colours that random fish and mutations can get. */
    public static List<String> ids() {
        return GeneticsData.get().pool(BettaLoci.BODY_COLOR);
    }

    public static List<String> iridescentIds() {
        return GeneticsData.get().pool(BettaLoci.IRIDESCENCE_COLOR);
    }

    public static boolean isKnown(String id) {
        return GeneticsData.get().isColor(id);
    }

    public static int rgb(String id) {
        return GeneticsData.get().rgb(id, FALLBACK_RGB);
    }

    public static String translationKey(String id) {
        return "color." + GeneticsData.nsPath(id);
    }
}
